{modal.type==='journal'&&<div className="lineitems"><h3>Journal lines</h3>{(form.entries||[]).map((l:any,i:number)=><div className="journalitem" key={i}><label>Account<Pick value={l.account} onChange={v=>update('entries',form.entries.map((x:any,n:number)=>n===i?{...x,account:v}:x))} options={accounts}/></label><label>Debit UGX<input type="number" min="0" step="1" value={l.debit} onChange={e=>update('entries',form.entries.map((x:any,n:number)=>n===i?{...x,debit:e.target.value}:x))}/></label><label>Credit UGX<input type="number" min="0" step="1" value={l.credit} onChange={e=>update('entries',form.entries.map((x:any,n:number)=>n===i?{...x,credit:e.target.value}:x))}/></label><button type="button" className="iconbutton" aria-label="Remove journal line" disabled={form.entries.length<=2} onClick={()=>update('entries',form.entries.filter((_:any,n:number)=>i!==n))}><X size={15}/></button></div>)}<button type="button" className="textbutton" onClick={()=>update('entries',[...form.entries,{account:'Bank',debit:0,credit:0}])}><Plus size={15}/>Add journal line</button><div className="documenttotal"><span>Debits {fmt(form.entries.reduce((s:number,l:any)=>s+Number(l.debit),0))}</span><span>Credits {fmt(form.entries.reduce((s:number,l:any)=>s+Number(l.credit),0))}</span><strong>Difference {fmt(form.entries.reduce((s:number,l:any)=>s+Number(l.debit)-Number(l.credit),0))}</strong></div></div>}
{!['import','pay','reconciliation'].includes(modal.type)&&<label className="noteslabel">{modal.type==='email'?'Message':modal.type==='void'?'Reason for reversal':'Notes'}<textarea required={modal.type==='void'} rows={3} value={form[modal.type==='void'?'reason':'notes']||''} onChange={e=>update(modal.type==='void'?'reason':'notes',e.target.value)}/></label>}
{['invoice','bill','expense','credit'].includes(modal.type)&&<><label className="checklabel"><Checkbox checked={!!form.intercompany} onCheckedChange={v=>update('intercompany',v===true)}/>Transaction between WMK and Hagadol</label>{form.intercompany&&<label className="noteslabel">Matching internal transaction reference<input required value={form.intercompanyRef||''} onChange={e=>update('intercompanyRef',e.target.value)}/></label>}</>}
