{['invoice','bill','expense','credit','receipt','payment','loan','loan_payment','transfer','journal'].includes(selected.type)&&!['Voided','Converted'].includes(selected.status)&&<button className="secondary" onClick={()=>{const r=selected;setDetail(null);setModal({type:'void'});setForm({id:r.id,date:day(),reason:'',expectedVersion:r.version})}}><RotateCcw size={15}/>Reverse</button>}
